void Renderer::free_rid(RID p_rid)
{
	if (!p_rid.is_valid()) {
		return;
	}

	if (Renderer::viewport && Renderer::viewport->free(p_rid)) {
		return;
	}
	if (RendererSceneCull::is_initialized() && RendererSceneCull::free(p_rid)) {
		return;
	}
	if (RendererUtilities::free(p_rid)) {
		return;
	}
}

