	shader_modes[RSE::SHADER_TEXTURE_BLIT].functions["blit"].built_ins["FRAGCOORD"] =
		constt(ShaderLanguage::TYPE_VEC4);

	shader_modes[RSE::SHADER_TEXTURE_BLIT].functions["blit"].built_ins["UV"] =
		constt(ShaderLanguage::TYPE_VEC2);
