PackedFloat32Array XRTracker::get_blend_shapes() const
{
	if (blend_shapes.size() == FT_MAX) {
		return blend_shapes;
	}
	PackedFloat32Array data;
	data.resize_initialized(FT_MAX);
	return data;
}

